Postfächer.source:
require ["fileinto","imap4flags","include","variables"];
global "move_to_folder";
# rule:[Nach Postfach sortieren]
if header :contains ["to","cc","bcc"] "alt@freemail.example"
{
	if header :contains "X-Forwarded-From" "student@hochschule.example"
	{
		addflag "$label1";
	}
	elsif header :contains "X-Forwarded-From" "tutor@hochschule.example"
	{
		addflag "$label1";
	}
	elsif header :contains ["X-Original-To","Delivered-To"] "info@filmprojekt.example"
	{
		addflag "$label2";
	}
	else
	{
		set "move_to_folder" "Konten";
	}
}
elsif header :contains ["to","cc","bcc"] ["login@meinname.example", "dev@meinname.example"]
{
	set "move_to_folder" "Konten";
}
elsif header :contains ["to","cc","bcc"] ["info@meinname.example", "buero@meinname.example", "rechnung@meinname.example"]
{
	addflag "$label3";
	if header :contains ["to","cc","bcc"] "rechnung@meinname.example"
	{
		addflag "$label4";
	}
}
elsif header :contains ["to","cc","bcc"] "kontakt@agentur.example"
{
	addflag "$label5";
}
elsif header :contains ["to","cc","bcc"] "privat@meinname.example"
{
	addflag "$label6";
}
elsif header :contains ["to","cc","bcc"] "admin@server.example"
{
	set "move_to_folder" "Admin";
}
else
{
	keep;
}

