Spam.source:
require ["body","fileinto","imap4flags","include","regex","variables"];
global "move_to_folder";
# rule:[Bekannte Störenfriede]
if anyof (header :contains "from" "angebote@werbung.example", header :contains "from" "gewinn@lotterie.example", header :contains "from" "news@spam-shop.example")
{
	setflag "\\Seen";
	set "move_to_folder" "Junk";
	return;
}
# rule:[Vom Server als Spam erkannt]
if anyof (header :contains "x-spam-flag" "yes", allof (header :regex "X-DSPAM-Result" "^(Spam|Virus|Bl[ao]cklisted)$", not header :contains "X-DSPAM-Reclassified" "Innocent"), allof (not header :regex "subject" "[[:graph:]]", body :regex "^[[:space:]]*http://[[:graph:]]+[[:space:]]*$"))
{
	if not address :domain :matches "from" ["*mein-verein.example", "*familie.example", "*firma.example", "*freunde.example"]
	{
		set "move_to_folder" "Junk";
		return;
	}
}
